insert into public.disposal_items (id,aliases,material,item_type,note) values
('expanded-20261027-001', ARRAY['생수병','생수페트병'], '페트병', '', '일반적인 무색 투명 생수병과 떼어낼 수 있는 비닐 라벨을 예시로 채웠어요. 무라벨·종이라벨·유색 제품이면 수정해 주세요. 뚜껑은 압착 후 닫는 안내를 따라 주세요.'),
('expanded-20261027-002', ARRAY['투명생수병','투명생수페트병','무색생수페트병'], '페트병', 'clear-drink', '비닐 라벨이 있는 구성을 예시로 채웠어요. 무라벨 제품이면 다른 재질 결합을 아니요로 바꿔 주세요.'),
('expanded-20261027-003', ARRAY['무라벨생수병','무라벨투명생수병','라벨없는생수병'], '페트병', 'clear-drink', '무색 투명한 무라벨 생수병 기준이에요. 뚜껑은 배출 전 압착 후 닫아 주세요.'),
('expanded-20261027-004', ARRAY['비닐라벨생수병','라벨있는투명생수병'], '페트병', 'clear-drink', '본체는 투명 음료용 PET, 분리 가능한 라벨은 비닐 포장재로 채웠어요. 실제 라벨 표시와 분리 가능 여부를 확인해 주세요.'),
('expanded-20261027-005', ARRAY['투명탄산음료페트병','투명콜라페트병'], '페트병', 'clear-drink', '무색 투명한 음료 PET와 비닐 라벨 기준이에요. 유색·종이 라벨이면 수정해 주세요.'),
('expanded-20261027-006', ARRAY['투명이온음료페트병','투명스포츠음료페트병'], '페트병', 'clear-drink', '무색 투명한 음료 PET와 비닐 라벨 기준이에요. 실제 구성에 맞춰 수정해 주세요.'),
('expanded-20261027-007', ARRAY['무라벨투명음료페트병'], '페트병', 'clear-drink', '무색 투명한 무라벨 음료 PET 기준이에요.'),
('expanded-20261027-008', ARRAY['유색음료페트병','갈색페트병','녹색페트병'], '페트병', 'other-pet', '무색 투명 생수·음료병 전용 수거 대상과 구분해요. 비닐 라벨 구성을 예시로 채웠어요.'),
